import { createClient } from 'https://esm.sh/@supabase/supabase-js@2.98.0';

type JsonRecord = Record<string, unknown>;
const MAX_BODY_BYTES = 128_000;
const DEFAULT_ALLOWED_ORIGINS = [
  'http://10.0.2.189:3000',
  'http://localhost:3000',
  'http://127.0.0.1:3000',
];

function configuredOrigins() {
  return (Deno.env.get('ALLOWED_ORIGINS') || DEFAULT_ALLOWED_ORIGINS.join(','))
    .split(',')
    .map((origin) => origin.trim())
    .filter(Boolean);
}

function corsHeaders(origin: string | null) {
  const allowed = origin && configuredOrigins().includes(origin) ? origin : '';
  return {
    'access-control-allow-origin': allowed,
    'access-control-allow-headers': 'authorization, x-client-info, apikey, content-type, x-gsa-signature',
    'access-control-allow-methods': 'POST, OPTIONS',
    'access-control-max-age': '86400',
    vary: 'Origin',
  };
}

function json(status: number, body: JsonRecord, origin: string | null = null) {
  return new Response(JSON.stringify(body), {
    status,
    headers: { 'content-type': 'application/json; charset=utf-8', ...corsHeaders(origin) },
  });
}

// Helpers from advertiser-admin
async function findExistingUser(admin: any, email: string) {
  for (let page = 1; page <= 100; page += 1) {
    const { data, error } = await admin.auth.admin.listUsers({ page, perPage: 200 });
    if (error) throw error;
    const match = data?.users?.find((user: any) => String(user.email || '').toLowerCase() === email);
    if (match) return match;
    if ((data?.users?.length || 0) < 200 || (data?.lastPage && page >= data.lastPage)) break;
  }
  return null;
}
function isUuid(value: unknown) {
  return typeof value === 'string'
    && /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(value);
}

// Helpers from webhook
function toHex(bytes: ArrayBuffer) {
  return Array.from(new Uint8Array(bytes)).map((byte) => byte.toString(16).padStart(2, '0')).join('');
}
async function hmacHex(secret: string, value: string) {
  const key = await crypto.subtle.importKey(
    'raw',
    new TextEncoder().encode(secret),
    { name: 'HMAC', hash: 'SHA-256' },
    false,
    ['sign'],
  );
  return toHex(await crypto.subtle.sign('HMAC', key, new TextEncoder().encode(value)));
}
function safeEqual(left: string, right: string) {
  if (left.length !== right.length) return false;
  let result = 0;
  for (let index = 0; index < left.length; index += 1) result |= left.charCodeAt(index) ^ right.charCodeAt(index);
  return result === 0;
}
export function normalizePaymentEvent(input: unknown) {
  if (!input || typeof input !== 'object') return null;
  const source = input as JsonRecord;
  const provider = String(source.provider || '').trim().slice(0, 50);
  const eventId = String(source.event_id || '').trim().slice(0, 200);
  const reference = String(source.reference || '').trim().slice(0, 200);
  const status = String(source.status || '').trim();
  if (!provider || !eventId || !reference || !['pending', 'processing', 'paid', 'failed', 'refunded', 'cancelled'].includes(status)) return null;
  return { provider, eventId, reference, status };
}

export async function handleRequest(request: Request) {
  const origin = request.headers.get('origin');
  if (request.method === 'OPTIONS') return new Response(null, { status: 204, headers: corsHeaders(origin) });
  if (origin && !configuredOrigins().includes(origin)) return json(403, { error: 'origin_not_allowed' }, origin);
  if (request.method !== 'POST') return json(405, { error: 'method_not_allowed' }, origin);

  const supabaseUrl = Deno.env.get('SUPABASE_URL');
  const anonKey = Deno.env.get('SUPABASE_ANON_KEY');
  const serviceRoleKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY');
  if (!supabaseUrl || !anonKey || !serviceRoleKey) return json(503, { error: 'server_not_configured' }, origin);

  const raw = await request.text();
  const providedSignature = String(request.headers.get('x-gsa-signature') || '').toLowerCase().replace(/^sha256=/, '');

  if (providedSignature) {
    const secret = Deno.env.get('ADVERTISING_WEBHOOK_SECRET');
    if (!secret) return json(503, { error: 'server_not_configured' }, origin);
    const expectedSignature = await hmacHex(secret, raw);
    if (!safeEqual(providedSignature, expectedSignature)) return json(401, { error: 'invalid_signature' }, origin);

    let payload: unknown;
    try {
      payload = JSON.parse(raw);
    } catch {
      return json(400, { error: 'invalid_json' }, origin);
    }
    const event = normalizePaymentEvent(payload);
    if (!event) return json(400, { error: 'invalid_event' }, origin);

    const admin = createClient(supabaseUrl, serviceRoleKey, { auth: { persistSession: false, autoRefreshToken: false } }) as any;
    const { data, error } = await admin.rpc('gsa_ads_process_payment_event', {
      p_provider: event.provider, p_event_id: event.eventId, p_reference: event.reference, p_status: event.status, p_payload: payload,
    });
    if (error) return json(error.code === 'P0002' ? 404 : 500, { error: 'event_processing_failed' }, origin);
    return json(200, { success: true, duplicate: Boolean(data?.duplicate), status: data?.status || event.status }, origin);
  }

  // Advertiser Admin Logic
  const authorization = request.headers.get('authorization') || '';
  if (!authorization.toLowerCase().startsWith('bearer ')) return json(401, { error: 'authentication_required' }, origin);

  let body: JsonRecord;
  try {
    body = JSON.parse(raw);
  } catch {
    return json(400, { error: 'invalid_json' }, origin);
  }

  if (body.action !== 'invite' || !isUuid(body.request_id)) {
    return json(400, { error: 'invalid_request' }, origin);
  }

  const userClient = createClient(supabaseUrl, anonKey, {
    global: { headers: { Authorization: authorization } },
    auth: { persistSession: false, autoRefreshToken: false },
  }) as any;
  const service = createClient(supabaseUrl, serviceRoleKey, {
    auth: { persistSession: false, autoRefreshToken: false },
  }) as any;

  const { data: userData, error: userError } = await userClient.auth.getUser();
  if (userError || !userData?.user) return json(401, { error: 'invalid_session' }, origin);

  const { data: target, error: targetError } = await userClient.rpc('gsa_admin_get_advertiser_invite_target', { p_request_id: body.request_id });
  if (targetError || !target?.advertiser_id || !target?.email) return json(403, { error: 'invite_not_allowed' }, origin);

  const email = String(target.email).trim().toLowerCase();
  const redirectTo = `${origin && configuredOrigins().includes(origin) ? origin : configuredOrigins()[0]}/anuncios/login`;

  if (target.auth_user_id) {
    const { error: accessError } = await service.auth.signInWithOtp({ email, options: { shouldCreateUser: false, emailRedirectTo: redirectTo } });
    if (accessError) return json(502, { error: 'access_email_failed' }, origin);
    return json(200, { success: true, advertiser_id: target.advertiser_id, already_linked: true, access_sent: true }, origin);
  }

  let authUser: any = null;
  const { data: inviteData, error: inviteError } = await service.auth.admin.inviteUserByEmail(email, {
    redirectTo, data: { gsa_role: 'advertiser', advertiser_id: target.advertiser_id },
  });

  if (inviteData?.user) {
    authUser = inviteData.user;
  } else if (inviteError) {
    authUser = await findExistingUser(service, email);
    if (!authUser) return json(502, { error: 'invite_failed' }, origin);
  }

  const { data: linked, error: linkError } = await userClient.rpc('gsa_admin_link_advertiser_auth', {
    p_advertiser_id: target.advertiser_id, p_auth_user_id: authUser.id,
  });
  if (linkError || !linked?.success) return json(500, { error: 'link_failed' }, origin);

  if (!inviteData?.user) {
    const { error: accessError } = await service.auth.signInWithOtp({ email, options: { shouldCreateUser: false, emailRedirectTo: redirectTo } });
    if (accessError) return json(502, { error: 'access_email_failed' }, origin);
  }

  return json(200, { success: true, advertiser_id: target.advertiser_id, email, invited: Boolean(inviteData?.user) }, origin);
}

if (import.meta.main) Deno.serve(handleRequest);
